   103  void UdpLayer::parseNextLayer()
   104  {
   105          if (m_DataLen <= sizeof(udphdr))
   106                  return;
   107
   108          uint16_t portDst = getDstPort();
   109          uint16_t portSrc = getSrcPort();
   110
   111          uint8_t* udpData = m_Data + sizeof(udphdr);
   112          size_t udpDataLen = m_DataLen - sizeof(udphdr);
   113
   114          if ((portSrc == 68 && portDst == 67) || (portSrc == 67 && portDst == 68) || (portSrc == 67 && portDst == 67))
   115                  m_NextLayer = new DhcpLayer(udpData, udpDataLen, this, m_Packet);
   116          else if (VxlanLayer::isVxlanPort(portDst))
   117                  m_NextLayer = new VxlanLayer(udpData, udpDataLen, this, m_Packet);
   118          else if (DnsLayer::isDataValid(udpData, udpDataLen) && (DnsLayer::isDnsPort(portDst) || DnsLayer::isDnsPort(portSrc)))
   119                  m_NextLayer = new DnsLayer(udpData, udpDataLen, this, m_Packet);
   120          else if(SipLayer::isSipPort(portDst) || SipLayer::isSipPort(portSrc))
   121          {
   122                  if (SipRequestFirstLine::parseMethod((char*)udpData, udpDataLen) != SipRequestLayer::SipMethodUnknown)
   123                          m_NextLayer = new SipRequestLayer(udpData, udpDataLen, this, m_Packet);
   124                  else if (SipResponseFirstLine::parseStatusCode((char*)udpData, udpDataLen) != SipResponseLayer::SipStatusCodeUnknown
   125                                                  && SipResponseFirstLine::parseVersion((char*)udpData, udpDataLen) != "")
   126                          m_NextLayer = new SipResponseLayer(udpData, udpDataLen, this, m_Packet);
   127                  else
   128                          m_NextLayer = new PayloadLayer(udpData, udpDataLen, this, m_Packet);
   129          }
   130          else if ((RadiusLayer::isRadiusPort(portDst) || RadiusLayer::isRadiusPort(portSrc)) && RadiusLayer::isDataValid(udpData, udpDataLen))
   131                  m_NextLayer = new RadiusLayer(udpData, udpDataLen, this, m_Packet);
   132          else if ((GtpV1Layer::isGTPv1Port(portDst) || GtpV1Layer::isGTPv1Port(portSrc)) && GtpV1Layer::isGTPv1(udpData, udpDataLen))
   133                  m_NextLayer = new GtpV1Layer(udpData, udpDataLen, this, m_Packet);
   134          else if ((DhcpV6Layer::isDhcpV6Port(portSrc) || DhcpV6Layer::isDhcpV6Port(portDst)) && (DhcpV6Layer::isDataValid(udpData, udpDataLen)))
   135                  m_NextLayer = new DhcpV6Layer(udpData, udpDataLen, this, m_Packet);
   136          else if ((NtpLayer::isNTPPort(portSrc) || NtpLayer::isNTPPort(portDst)) && NtpLayer::isDataValid(udpData, udpDataLen))
   137                  m_NextLayer = new NtpLayer(udpData, udpDataLen, this, m_Packet);
   138          else if (SomeIpLayer::isSomeIpPort(portSrc) || SomeIpLayer::isSomeIpPort(portDst))
   139                  m_NextLayer = SomeIpLayer::parseSomeIpLayer(udpData, udpDataLen, this, m_Packet);
   140          else if ((WakeOnLanLayer::isWakeOnLanPort(portDst) && WakeOnLanLayer::isDataValid(udpData, udpDataLen)))
   141                  m_NextLayer = new WakeOnLanLayer(udpData, udpDataLen, this, m_Packet);
   142          else
   143                  m_NextLayer = new PayloadLayer(udpData, udpDataLen, this, m_Packet);
   144  }
